///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Send
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Send = async function () {
    const sbmOptions = {
        id: "tx_fn_Send",
        method: "post",
        action: "/support/question.do?method=registerQuestionEmail",
        ref: "dma_SendReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16100.tx_fn_Send" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.send
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.send = async function () {
    /* sdd-asis-lifecycle:begin fn_Send — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_quesTitle'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "질의제목"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_quesTitle'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_questrNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "이름"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_questrNm'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('txa_quesContn'))) {
        return;
    }
    if ($c.cm.fn_IsNotNull($c.util.getComponent('ipt_questrEmail'))) {
        $c.util.getComponent("ipt_questrEmail").setValue($c.str.trim($c.util.getComponent('ipt_questrEmail').getValue()));
        if (!$c.cm.fn_CheckEmail($c.util.getComponent('ipt_questrEmail').getValue())) {
            return;
        }
    }
    scwin.form_questionForm.action = "/support/question.do?method=registerQuestionEmail";
    await scwin.tx_fn_Send();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clear
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.clear = async function () {
    /* sdd-asis-lifecycle:begin fn_Clear — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_quesTitle").setValue("");
    $c.util.getComponent("txa_quesContn").setValue("");
    await scwin.checkByte($c.util.getComponent('txa_quesContn'));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.checkByte = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_CheckByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const standardByte = 800;
    const contnByte = scwin.getByte(_obj);
    const byteCntObj = $c.util.getComponent("txt_byteCnt");
    byteCntObj.innerText = "내용(" + (contnByte) + "/800 byte)";
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getByte = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0D') {
            inc = 1;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calcContn
 * @author Inswave
 * @date 2026. 09. 29
 * @param _contn _maximum
 * @returns
 * @hidden N
*/
scwin.calcContn = function (_contn, _maximum) {
    /* sdd-asis-lifecycle:begin fn_CalcContn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (ch === '\n') {
            if (_contn.charAt(i - 1) !== '\r') {
                inc = 1;
            }
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                if (ch === '<' || ch === '>') {
                    inc = 4;
                } else {
                    inc = 1;
                }
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
    /* sdd-asis-lifecycle:end */
};
